INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_039', 'topic_wassce_p2_math_rat', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Eight workers can build a wall in 15 days. Working at the same rate, how many days will it take 12 workers to build the same wall?', 'multiple_choice', NULL, '["A. 22.5 days","B. 20 days","C. 10 days","D. 8 days"]', 'C', 'The job needs 8 × 15 = 120 worker-days. With 12 workers the time is 120 ÷ 12 = 10 days. (22.5 days wrongly uses direct proportion; more workers means fewer days.) Therefore the correct answer is C: 10 days.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
